{
  "name": "Recova - Terms & Conditions",
  "description": "A professional, responsive, and interactive legal page for the Recova app, featuring a clean modern UI, table of contents, and an AI-powered terms assistant."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect } from 'react';
import { Header } from './components/Header';
import { Sidebar } from './components/Sidebar';
import { TermsSection } from './components/TermsSection';
import { ContactCard } from './components/ContactCard';
import { AiAssistant } from './components/AiAssistant';
import { TERMS_DATA } from './constants';

const App: React.FC = () => {
  const [activeSection, setActiveSection] = useState<string>(TERMS_DATA[0].id);

  useEffect(() => {
    const handleScroll = () => {
      const scrollPosition = window.scrollY + 100;

      for (const section of TERMS_DATA) {
        const element = document.getElementById(section.id);
        if (element) {
          const { offsetTop, offsetHeight } = element;
          if (scrollPosition >= offsetTop && scrollPosition < offsetTop + offsetHeight) {
            setActiveSection(section.id);
            break;
          }
        }
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <div className="min-h-screen flex flex-col">
      <Header />

      <main className="flex-grow container mx-auto px-4 sm:px-6 lg:px-8 py-12 lg:py-20">
        <div className="lg:flex lg:gap-16">
          {/* Desktop Sidebar */}
          <aside className="hidden lg:block w-72 flex-shrink-0">
            <div className="sticky top-28">
              <Sidebar activeSection={activeSection} />
            </div>
          </aside>

          {/* Content Area */}
          <div className="flex-grow max-w-3xl">
            <header className="mb-12">
              <h1 className="text-4xl sm:text-5xl font-extrabold text-slate-900 mb-4 tracking-tight">
                Terms & Conditions
              </h1>
              <div className="flex items-center gap-3 text-slate-500 font-medium">
                <span className="inline-block px-3 py-1 bg-indigo-50 text-indigo-600 rounded-full text-sm">
                  RECOVA
                </span>
                <span className="text-slate-300">|</span>
                <span>Last updated: 17 January 2026</span>
              </div>
              <p className="mt-8 text-lg text-slate-600 leading-relaxed">
                By accessing or using Recova, you agree to these Terms & Conditions. 
                If you do not agree, please do not use the app.
              </p>
            </header>

            <div className="space-y-16">
              {TERMS_DATA.map((section) => (
                <TermsSection 
                  key={section.id} 
                  id={section.id} 
                  title={section.title} 
                  content={section.content}
                  important={section.important}
                />
              ))}
            </div>

            <ContactCard />
          </div>
        </div>
      </main>

      <footer className="bg-white border-t border-slate-200 py-12">
        <div className="container mx-auto px-4 text-center">
          <p className="text-slate-500 text-sm">
            &copy; {new Date().getFullYear()} Recova App. All rights reserved.
          </p>
          <p className="text-slate-400 text-xs mt-2">
            Providing recovery and readiness insights for your peak performance.
          </p>
        </div>
      </footer>

      {/* Floating AI Assistant to help explain legal terms */}
      <AiAssistant />
    </div>
  );
};

export default App;

import React from 'react';
import { TERMS_DATA } from '../constants';

interface SidebarProps {
  activeSection: string;
}

export const Sidebar: React.FC<SidebarProps> = ({ activeSection }) => {
  const handleClick = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      window.scrollTo({
        top: element.offsetTop - 100,
        behavior: 'smooth'
      });
    }
  };

  return (
    <div className="space-y-4">
      <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-6">Contents</h3>
      <ul className="space-y-1">
        {TERMS_DATA.map((item) => (
          <li key={item.id}>
            <button
              onClick={() => handleClick(item.id)}
              className={`w-full text-left py-2 px-3 rounded-lg text-sm transition-all duration-200 ${
                activeSection === item.id
                  ? 'bg-indigo-50 text-indigo-700 font-semibold shadow-sm border-l-4 border-indigo-600'
                  : 'text-slate-500 hover:bg-slate-100 hover:text-slate-900'
              }`}
            >
              {item.title.split('. ')[1]}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
};

import React from 'react';

interface TermsSectionProps {
  id: string;
  title: string;
  content: React.ReactNode;
  important?: boolean;
}

export const TermsSection: React.FC<TermsSectionProps> = ({ id, title, content, important }) => {
  return (
    <section id={id} className={`scroll-mt-28 transition-all duration-300 ${important ? 'group' : ''}`}>
      <div className={`p-8 rounded-2xl transition-all duration-500 ${
        important 
          ? 'bg-red-50/50 border border-red-100 shadow-sm ring-4 ring-red-50/20' 
          : 'bg-white border border-slate-100 shadow-sm hover:shadow-md'
      }`}>
        <div className="flex items-center gap-3 mb-6">
          <h2 className={`text-2xl font-bold ${important ? 'text-red-900' : 'text-slate-900'}`}>
            {title}
          </h2>
          {important && (
            <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-red-600 text-white uppercase tracking-wider animate-pulse">
              Important
            </span>
          )}
        </div>
        <div className={`prose prose-slate max-w-none text-lg leading-relaxed ${
          important ? 'text-red-800' : 'text-slate-600'
        }`}>
          {content}
        </div>
      </div>
    </section>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";

const SYSTEM_INSTRUCTION = `
You are a friendly legal assistant for the RECOVA app. 
Your job is to explain the Terms & Conditions to users in simple, plain language. 
The RECOVA app provides recovery and readiness insights but is NOT a medical app.

Key points to remember:
- It's NOT medical advice.
- Users must be truthful.
- Data is handled by Privacy Policy.
- It's governed by Indian law.

Be concise, reassuring, and always remind the user that your summary does not replace the full legal text.
`;

export const AiAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [response, setResponse] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    if (isOpen) scrollToBottom();
  }, [isOpen, response]);

  const handleQuery = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!query.trim()) return;

    const userQuery = query;
    setQuery('');
    setResponse('');
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const result = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userQuery,
        config: {
          systemInstruction: SYSTEM_INSTRUCTION,
        },
      });

      setResponse(result.text || "I'm sorry, I couldn't process that. Please try again.");
    } catch (error) {
      console.error("AI Error:", error);
      setResponse("I'm having trouble connecting right now. Please check the full text above or contact support.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[60]">
      {/* Trigger Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="w-14 h-14 bg-indigo-600 hover:bg-indigo-700 text-white rounded-full shadow-2xl flex items-center justify-center transition-all hover:scale-110 active:scale-95 group relative"
      >
        <div className="absolute -top-12 right-0 bg-slate-900 text-white text-xs py-1 px-3 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none">
          Questions about these terms?
          <div className="absolute bottom-0 right-5 translate-y-full w-2 h-2 bg-slate-900 rotate-45"></div>
        </div>
        {isOpen ? (
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        ) : (
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
          </svg>
        )}
      </button>

      {/* Chat Window */}
      {isOpen && (
        <div className="absolute bottom-20 right-0 w-[90vw] sm:w-[400px] bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden flex flex-col animate-in slide-in-from-bottom-4 duration-300">
          <div className="bg-indigo-600 p-4 text-white flex items-center gap-3">
            <div className="w-8 h-8 bg-white/20 rounded-lg flex items-center justify-center">
              <span className="text-xs font-bold">AI</span>
            </div>
            <div>
              <h4 className="font-bold text-sm">Terms Assistant</h4>
              <p className="text-[10px] text-indigo-200">Powered by Gemini</p>
            </div>
          </div>

          <div className="flex-grow p-4 min-h-[200px] max-h-[400px] overflow-y-auto space-y-4 bg-slate-50">
            <div className="bg-white p-3 rounded-2xl rounded-tl-none border border-slate-100 text-sm text-slate-700 shadow-sm max-w-[85%]">
              Hi! I'm the Recova Terms Assistant. Ask me anything about our Terms & Conditions and I'll explain it simply.
            </div>

            {response && (
              <div className="bg-indigo-50 p-3 rounded-2xl rounded-tl-none border border-indigo-100 text-sm text-slate-800 shadow-sm max-w-[85%]">
                {response}
              </div>
            )}

            {isLoading && (
              <div className="flex gap-2 p-2">
                <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce"></div>
                <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce delay-100"></div>
                <div className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce delay-200"></div>
              </div>
            )}
            <div ref={chatEndRef} />
          </div>

          <form onSubmit={handleQuery} className="p-4 bg-white border-t border-slate-100 flex gap-2">
            <input
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="e.g. Is this a medical app?"
              className="flex-grow bg-slate-100 border-none rounded-full px-4 py-2 text-sm focus:ring-2 focus:ring-indigo-500 transition-all outline-none"
              disabled={isLoading}
            />
            <button
              type="submit"
              disabled={isLoading || !query.trim()}
              className="bg-indigo-600 text-white p-2 rounded-full hover:bg-indigo-700 disabled:opacity-50 transition-colors shadow-lg shadow-indigo-200"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 rotate-90" viewBox="0 0 20 20" fill="currentColor">
                <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" />
              </svg>
            </button>
          </form>
        </div>
      )}
    </div>
  );
};

