import React from 'react';
import { TERMS_DATA } from '../constants';

interface SidebarProps {
  activeSection: string;
}

export const Sidebar: React.FC<SidebarProps> = ({ activeSection }) => {
  const handleClick = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      window.scrollTo({
        top: element.offsetTop - 120,
        behavior: 'smooth'
      });
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-3">
        <div className="w-1 h-6 bg-indigo-600 rounded-full"></div>
        <h3 className="text-sm font-extrabold text-slate-900 uppercase tracking-widest">Navigation</h3>
      </div>
      <ul className="space-y-1.5">
        {TERMS_DATA.map((item) => (
          <li key={item.id}>
            <button
              onClick={() => handleClick(item.id)}
              className={`w-full text-left py-3 px-4 rounded-xl text-sm transition-all duration-300 group flex items-center justify-between ${
                activeSection === item.id
                  ? 'bg-slate-900 text-white font-bold shadow-xl shadow-slate-200 translate-x-1'
                  : 'text-slate-500 hover:bg-slate-100 hover:text-slate-900 font-medium'
              }`}
            >
              <span className="truncate">{item.title.split('. ')[1]}</span>
              {activeSection === item.id && (
                <svg className="w-4 h-4 text-indigo-400" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M10.293 3.293a1 1 0 011.414 0l6 6a1 1 0 010 1.414l-6 6a1 1 0 01-1.414-1.414L14.586 11H3a1 1 0 110-2h11.586l-4.293-4.293a1 1 0 010-1.414z" clipRule="evenodd"></path>
                </svg>
              )}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
};

