import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";

const SYSTEM_INSTRUCTION = `
Explain RECOVA's Terms & Conditions in plain language. 
- It's NOT medical advice.
- Users must be truthful.
- Data is handled by Privacy Policy.
Be concise.
`;

export const AiAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [query, setQuery] = useState('');
  const [response, setResponse] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    if (isOpen) scrollToBottom();
  }, [isOpen, response]);

  const handleQuery = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!query.trim()) return;

    const userQuery = query;
    setQuery('');
    setResponse('');
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const result = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userQuery,
        config: { systemInstruction: SYSTEM_INSTRUCTION },
      });

      setResponse(result.text || "Error processing request.");
    } catch (error) {
      setResponse("Could not connect to AI. Please refer to the text above.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed bottom-4 right-4 z-[60]">
      <button
        onClick={() => setIsOpen(!isOpen)}
        className="w-12 h-12 bg-slate-900 text-white rounded-full shadow-lg flex items-center justify-center hover:bg-slate-800 transition-colors"
      >
        {isOpen ? (
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
        ) : (
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8.228 9c.549-1.165 2.03-2 3.772-2 2.21 0 4 1.343 4 3 0 1.4-1.278 2.575-3.006 2.907-.542.104-.994.54-.994 1.093m0 3h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
        )}
      </button>

      {isOpen && (
        <div className="absolute bottom-16 right-0 w-[320px] bg-white rounded-lg shadow-xl border border-slate-200 flex flex-col overflow-hidden">
          <div className="bg-slate-50 p-3 border-b border-slate-200">
            <h4 className="font-bold text-xs uppercase tracking-widest text-slate-500">Terms Helper</h4>
          </div>

          <div className="p-4 max-h-[300px] overflow-y-auto space-y-4 text-sm">
            <div className="bg-slate-100 p-3 rounded-lg text-slate-700">
              Ask me any question about our Terms & Conditions.
            </div>

            {response && (
              <div className="bg-indigo-50 p-3 rounded-lg text-slate-800 border border-indigo-100">
                {response}
              </div>
            )}

            {isLoading && <div className="text-xs text-slate-400">Thinking...</div>}
            <div ref={chatEndRef} />
          </div>

          <form onSubmit={handleQuery} className="p-3 border-t border-slate-200 flex gap-2">
            <input
              type="text"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Ask a question..."
              className="flex-grow bg-slate-50 rounded border border-slate-200 px-3 py-1.5 text-xs outline-none focus:border-indigo-500"
              disabled={isLoading}
            />
            <button
              type="submit"
              disabled={isLoading || !query.trim()}
              className="bg-slate-900 text-white px-3 py-1.5 rounded text-xs hover:bg-slate-800 disabled:opacity-50"
            >
              Send
            </button>
          </form>
        </div>
      )}
    </div>
  );
};
